/// Exact-key lookup in the transcribed Main table. Wildcard matching is
/// the caller's job (it mirrors ProcessDICOM's five substitutions).
pub(crate) fn dicom_main_entry(key: &str) -> Option<&'static DicomDictEntry> {
    DICOM_MAIN
        .binary_search_by_key(&key, |&(k, _)| k)
        .ok()
        .map(|index| &DICOM_MAIN[index].1)
}

/// Registered-UID name, or `None` for an unregistered UID (which ExifTool
/// reports verbatim -- there is no `Unknown (...)` fallback for UIDs).
pub(crate) fn dicom_uid_name(uid: &str) -> Option<&'static str> {
    DICOM_UID
        .binary_search_by_key(&uid, |&(k, _)| k)
        .ok()
        .map(|index| DICOM_UID[index].1)
}
